glsl3.vert:
precision highp float;
in vec3 a_position;
vec4 vert () {
  return vec4(a_position.xy, 0.0, 1.0);
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
uniform sampler2D colorTex;
uniform sampler2D ndTex;
layout(std140) uniform EdgeConstants {
  vec4 texel;
  vec4 params;
  vec4 inkColor;
};
float zOf (float d) { return d >= 0.985 ? 1.0e6 : params.z + d * (params.w - params.z); }
vec3 dec (vec2 e) { vec2 n = e * 2.0 - 1.0; return vec3(n, sqrt(max(0.0, 1.0 - dot(n, n)))); }
vec4 frag () {
  vec2 uv = gl_FragCoord.xy * texel.xy;
  vec4 c = texture(colorTex, uv);
  vec4 n0 = texture(ndTex, uv);
  float z0 = zOf(n0.a);
  float thr = z0 - max(z0 * params.x, params.y);
  float line = 0.0;
  for (int i = 0; i < 16; i++) {
    float a = float(i) * 0.3926991;
    vec2 dir = vec2(cos(a), sin(a)) * texel.xy * texel.z;
    float s1 = zOf(texture(ndTex, uv + dir).a);
    float s2 = zOf(texture(ndTex, uv + dir * 0.55).a);
    if (min(s1, s2) < thr) { line = 1.0; break; }
  }
  if (line < 0.5 && n0.a < 0.985) {
    vec3 N0 = dec(n0.xy);
    for (int i = 0; i < 4; i++) {
      vec2 o = (i == 0 ? vec2(1.0, 0.0) : i == 1 ? vec2(-1.0, 0.0) : i == 2 ? vec2(0.0, 1.0) : vec2(0.0, -1.0)) * texel.w * texel.xy;
      vec4 n = texture(ndTex, uv + o);
      if (n.a >= 0.985) { line = 1.0; break; }
      if (n0.b < 0.002 || n.b < 0.002) continue;
      if (abs(n.b - n0.b) > 0.002 || dot(N0, dec(n.xy)) < 0.55) { line = 1.0; break; }
    }
  }
  return c * (1.0 - line) + vec4(inkColor.rgb, 1.0) * line;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

